/**
 * Foundation cost math — ported VERBATIM from SignEstimate Pro
 * (src/pages/NewFoundationEstimate.jsx: getConcreteMixes / getConcreteAdmixtures /
 *  getSmallLoadFee / getFuelSurcharge / calcItemCost / concrete truck totals).
 *
 * Do not "improve" these formulas — they must stay identical to SignEstimate Pro.
 * `settings` is the Settings entity key/value map; `inventory` is FoundationInventory
 * rows plus concrete suppliers normalized out of LaborServiceInventory.
 */

export const getConcreteMixes = (invItem) => [
  { id: '3500_ae', name: '3500 AIR ENTRAINED (AE)', price: invItem?.mix_3500_price ?? 195.40, desc: 'Often used for driveways, slabs, and moderate-load footings.' },
  { id: '4000_ae', name: '4000 AIR ENTRAINED (AE)', price: invItem?.mix_4000_price ?? 201.00, desc: 'STANDARD. Used for sign foundations, commercial flatwork, and structural footings requiring good durability.' },
  { id: '4500_ae', name: '4500 AIR ENTRAINED (AE)', price: invItem?.mix_4500_price ?? 208.70, desc: 'Used for heavy-duty commercial slabs and heavy traffic areas.' },
  { id: '5000_ae', name: '5000 AIR ENTRAINED (AE)', price: invItem?.mix_5000_price ?? 214.60, desc: 'High-strength mix for heavy structural columns, pillars, and extreme load conditions.' },
  { id: 'fast_set', name: 'FAST SET', price: invItem?.mix_fast_set_price ?? 248.00, desc: 'Quick-curing concrete used when rapid strength gain is needed to minimize downtime.' },
];

export const getConcreteAdmixtures = (invItem) => [
  { id: 'calcium_chloride', name: 'Calcium Chloride', price: invItem?.admix_calcium_chloride_price ?? 8.50, desc: 'Speeds up how fast the concrete dries. SELECT THIS when pouring in cold weather so it doesn\'t freeze before it sets. WARNING: Do NOT select this if using Rebar, as it causes rust!' },
  { id: 'set_retarding', name: 'Set-Retarding Admix (Type D)', price: invItem?.admix_set_retarding_price ?? 4.50, desc: 'Slows down how fast the concrete dries. SELECT THIS when pouring in very hot weather, or if the concrete truck has a very long drive to the site.' },
  { id: 'water_reducing', name: 'Water-Reducing Admix (Type A)', price: invItem?.admix_water_reducing_price ?? 4.25, desc: 'Makes the concrete easier to pour without weakening it. SELECT THIS if you need the concrete to flow better into tight forms or around lots of rebar.' },
  { id: 'fibers', name: 'Fibers', price: invItem?.admix_fibers_price ?? 12.50, desc: 'Tiny fibers mixed into the concrete to prevent small cracks. SELECT THIS for large flat slabs (like monument sign pads) or if the foundation will take physical abuse.' },
  { id: 'winter_service', name: 'Winter Service', price: invItem?.admix_winter_service_price ?? 5.50, desc: 'A fee the plant charges to use hot water so the mix doesn\'t freeze. SELECT THIS always during winter months when temperatures are freezing.' },
];

// Get the small load fee for a given number of yards based on supplier bracket pricing
export const getSmallLoadFee = (yards, invItem) => {
  if (yards >= 5) return 0;
  if (yards >= 4.5) return invItem?.small_load_fee_4_5_4_75 ?? 40;
  if (yards >= 4) return invItem?.small_load_fee_4_4_25 ?? 80;
  if (yards >= 3) return invItem?.small_load_fee_3_3_75 ?? 105;
  if (yards >= 2) return invItem?.small_load_fee_2_2_75 ?? 120;
  if (yards >= 1) return invItem?.small_load_fee_1_1_75 ?? 150;
  return invItem?.small_load_fee_1_1_75 ?? 150; // under 1 yd still gets the smallest bracket fee
};

export const getFuelSurcharge = (invItem) => {
  return invItem?.fuel_surcharge ?? 30;
};

/** Normalize a LaborServiceInventory concrete supplier into the shape this math expects. */
export const normalizeConcreteSupplier = (row) => ({
  id: row.id,
  material_name: row.service_name,
  material_description: row.description || "",
  material_type: "concrete_service",
  supplier: row.vendor_name || row.service_name,
  cost_per_unit: row.default_rate || 0,
  unit: "cy",
  minimum_order_yards: row.minimum_order_yards || 0,
  below_minimum_cost_per_cy: row.below_minimum_cost_per_cy || 0,
  minimum_cost: row.minimum_charge || 0,
  mix_3500_price: row.mix_3500_price || 0,
  mix_4000_price: row.mix_4000_price || 0,
  mix_4500_price: row.mix_4500_price || 0,
  mix_5000_price: row.mix_5000_price || 0,
  mix_fast_set_price: row.mix_fast_set_price || 0,
  admix_calcium_chloride_price: row.admix_calcium_chloride_price || 0,
  admix_set_retarding_price: row.admix_set_retarding_price || 0,
  admix_water_reducing_price: row.admix_water_reducing_price || 0,
  admix_fibers_price: row.admix_fibers_price || 0,
  admix_winter_service_price: row.admix_winter_service_price || 0,
  small_load_fee_1_1_75: row.small_load_fee_1_1_75 || 0,
  small_load_fee_2_2_75: row.small_load_fee_2_2_75 || 0,
  small_load_fee_3_3_75: row.small_load_fee_3_3_75 || 0,
  small_load_fee_4_4_25: row.small_load_fee_4_4_25 || 0,
  small_load_fee_4_5_4_75: row.small_load_fee_4_5_4_75 || 0,
  fuel_surcharge: row.fuel_surcharge || 0,
  show_in_foundation: row.show_in_foundation !== false,
  _source: "labor_services",
});

export const calcItemCost = (item, inventory = [], settings = {}) => {
  const getSetting = (key, def) => parseFloat(settings[key] || def);

  const selectedConcrete = inventory.find(c => c.id === item.selected_concrete_id);
  const conc_cost = item.custom_concrete_cost_per_cy !== null && item.custom_concrete_cost_per_cy !== undefined
    ? item.custom_concrete_cost_per_cy
    : (selectedConcrete?.cost_per_unit || 0);

  // Find the selected rebar from inventory (matching the #size)
  const selectedRebar = inventory.find(r => r.material_type === 'rebar' && r.rebar_size === item.rebar_size);
  const pillarSelectedRebar = inventory.find(r => r.material_type === 'rebar' && r.rebar_size === (item.pillar_rebar_size || '#4'));
  const activeRebar = item.foundation_type === 'spread_foot' ? selectedRebar : pillarSelectedRebar;

  const rebar_cost = item.custom_rebar_cost_per_ft !== null && item.custom_rebar_cost_per_ft !== undefined
    ? item.custom_rebar_cost_per_ft
    : (activeRebar?.cost_per_unit || 0);

  const main_labor_rate = getSetting('foundation_main_labor_rate', 60);
  const rebar_time_cross_section = getSetting('foundation_rebar_time_cross_section', 0.05);
  const rebar_time_linear_ft = getSetting('foundation_rebar_time_linear_ft', 0.02);

  const forming_cost_per_sqft = getSetting('foundation_forming_cost_per_sqft', 2.50);
  const pouring_cost_per_cy = getSetting('foundation_pouring_cost_per_cy', 15);
  const finishing_cost_per_sqft = getSetting('foundation_finishing_cost_per_sqft', 1.25);

  const forming_mult = item.foundation_type === 'spread_foot'
    ? getSetting('foundation_forming_materials_spread_foot', 0.5)
    : getSetting('foundation_forming_materials_pillar', 0.75);

  let baseVolumeCY = 0;
  const lenIn = parseFloat(item.length_inches) || 0;
  const widIn = parseFloat(item.width_inches) || 0;
  const depIn = parseFloat(item.depth_inches) || 0;
  const diaIn = parseFloat(item.diameter) || 0;

  if (item.foundation_type === 'spread_foot') {
    baseVolumeCY = ((lenIn / 12) * (widIn / 12) * (depIn / 12)) / 27;
  } else {
    const r = (diaIn / 2) / 12;
    baseVolumeCY = (Math.PI * r * r * (depIn / 12)) / 27;
  }
  baseVolumeCY = baseVolumeCY * (item.quantity || 1);

  const volumeCY = item.custom_concrete_qty !== null && item.custom_concrete_qty !== undefined ? item.custom_concrete_qty : baseVolumeCY;

  let concreteCost = 0;
  let baseBags = null;
  let concreteBags = null;

  if (selectedConcrete?.material_type === 'bagged_concrete') {
    baseBags = Math.ceil(baseVolumeCY * 45); // ~45 80lb bags per CY
    concreteBags = item.custom_concrete_qty !== null && item.custom_concrete_qty !== undefined ? item.custom_concrete_qty : baseBags;
    concreteCost = concreteBags * conc_cost;
  }

  let rebarCost = 0;
  let baseRebarFt = 0;
  let totalIntersections = 0;

  if (item.include_rebar && item.foundation_type === 'spread_foot') {
    const nBarsL = Math.floor(widIn / (parseFloat(item.rebar_spacing_width) || 12)) + 1;
    const nBarsW = Math.floor(lenIn / (parseFloat(item.rebar_spacing_length) || 12)) + 1;
    const layers = parseInt(item.rebar_layers) || 1;
    const horizontalFt = (nBarsL * (lenIn / 12) + nBarsW * (widIn / 12)) * layers;

    const numIntersections = nBarsL * nBarsW * layers;
    const verticalLengthFt = Math.max(0, depIn - 6) / 12;
    const verticalFt = numIntersections * verticalLengthFt;

    baseRebarFt = (horizontalFt + verticalFt) * (parseInt(item.quantity) || 1);
    totalIntersections = numIntersections * (parseInt(item.quantity) || 1);
  } else if (item.include_rebar && item.foundation_type === 'pillar') {
    const hoopDia = parseFloat(item.pillar_rebar_hoop_diameter) || Math.max(0, diaIn - 4);
    const safeHoopDia = Math.min(hoopDia, Math.max(0, diaIn - 4));
    const layers = parseInt(item.pillar_rebar_layers) || 1;
    const verticalCount = parseInt(item.pillar_vertical_rebar_count) || 4;

    const hoopLengthFt = (Math.PI * safeHoopDia) / 12;
    const totalHoopFt = hoopLengthFt * layers;

    const verticalLengthFt = Math.max(0, depIn - 6) / 12;
    const totalVerticalFt = verticalCount * verticalLengthFt;

    baseRebarFt = (totalHoopFt + totalVerticalFt) * (parseInt(item.quantity) || 1);
    totalIntersections = (layers * verticalCount) * (parseInt(item.quantity) || 1);
  }

  const rebarFt = item.custom_rebar_qty !== null && item.custom_rebar_qty !== undefined ? item.custom_rebar_qty : baseRebarFt;
  if (item.include_rebar) {
    const materialCost = rebarFt * rebar_cost;
    const totalTimeHours = (totalIntersections * rebar_time_cross_section) + (rebarFt * rebar_time_linear_ft);
    const laborCost = totalTimeHours * main_labor_rate;
    rebarCost = materialCost + laborCost;
  }

  let formingCost = 0;
  let baseFormingQty = 0;
  const selectedForming = inventory.find(i => i.id === item.selected_forming_id);
  const forming_rate = item.custom_forming_rate !== null && item.custom_forming_rate !== undefined ? item.custom_forming_rate : (selectedForming?.cost_per_unit || 0);

  if (item.include_forming) {
    const perim = item.foundation_type === 'spread_foot'
      ? 2 * (lenIn + widIn) / 12
      : Math.PI * diaIn / 12;
    const formingAreaSqFt = perim * (depIn / 12);

    // Calculate pcs based on perimeter — standard 16ft lengths
    baseFormingQty = Math.ceil(perim / 16) * (parseInt(item.quantity) || 1);
    const formingQty = item.custom_forming_qty !== null && item.custom_forming_qty !== undefined ? item.custom_forming_qty : baseFormingQty;

    const formingMaterialCost = formingQty * forming_rate;

    // Keep old labor calculation logic
    const laborCost = formingAreaSqFt * (parseInt(item.quantity) || 1) * forming_cost_per_sqft;
    formingCost = laborCost + formingMaterialCost + (concreteCost * forming_mult);
  }

  let finishingCost = 0;
  let baseFinishingHours = 0;
  const finishing_rate = item.custom_finishing_rate !== null && item.custom_finishing_rate !== undefined ? item.custom_finishing_rate : main_labor_rate;

  if (item.include_finishing) {
    const topArea = item.foundation_type === 'spread_foot'
      ? (lenIn * widIn) / 144
      : Math.PI * ((diaIn / 2 / 12) ** 2);

    // back out hours from sqft cost formula
    const defaultFinishingCost = topArea * (parseInt(item.quantity) || 1) * finishing_cost_per_sqft;
    baseFinishingHours = defaultFinishingCost / main_labor_rate;
    const finishingHours = item.custom_finishing_hours !== null && item.custom_finishing_hours !== undefined ? item.custom_finishing_hours : baseFinishingHours;

    finishingCost = finishingHours * finishing_rate;
  }

  const pouringCost = volumeCY * pouring_cost_per_cy;

  let excavationCost = 0;
  let baseExcavationHours = 0;
  const excVol = volumeCY * 1.25;
  if (item.excavation_method === 'hand_dig' || !item.excavation_method) {
    const timePerCy = getSetting('foundation_hand_dig_time_per_cy', 2.0);
    baseExcavationHours = excVol * timePerCy;
  } else {
    const timePerCy = getSetting('foundation_equipment_excavation_time_per_cy', 0.5);
    baseExcavationHours = excVol * timePerCy;
  }

  const excavationHours = item.custom_excavation_hours !== null && item.custom_excavation_hours !== undefined ? item.custom_excavation_hours : baseExcavationHours;
  const excavation_rate = item.custom_excavation_rate !== null && item.custom_excavation_rate !== undefined ? item.custom_excavation_rate : main_labor_rate;

  excavationCost = excavationHours * excavation_rate;

  return {
    concreteCost,
    concreteBags,
    volumeCY,
    baseVolumeCY,
    baseBags,
    rebarCost,
    rebarFt,
    baseRebarFt,
    formingCost,
    formingQty: item.custom_forming_qty !== null && item.custom_forming_qty !== undefined ? item.custom_forming_qty : baseFormingQty,
    baseFormingQty,
    finishingCost,
    finishingHours: item.custom_finishing_hours !== null && item.custom_finishing_hours !== undefined ? item.custom_finishing_hours : baseFinishingHours,
    baseFinishingHours,
    pouringCost,
    excavationCost,
    excavationHours,
    baseExcavationHours,
    concreteRate: conc_cost,
    rebarRate: rebar_cost,
    formingRate: forming_rate,
    finishingRate: finishing_rate,
    excavationRate: excavation_rate,
    selectedConcreteName: selectedConcrete?.material_name || '',
    selectedRebarName: activeRebar?.material_name || '',
    selectedFormingName: selectedForming?.material_name || '',
    total: concreteCost + rebarCost + formingCost + finishingCost + pouringCost + excavationCost,
  };
};

/**
 * Project-level concrete delivery math: 9-yard trucks, quarter-yard rounding,
 * small-load fee bracket + fuel surcharge per truck, plus $100 per new sign location stop.
 */
export const calcConcreteDelivery = (project, items = [], inventory = []) => {
  const concreteServiceItems = items.filter((item) => {
    const inv = inventory.find(i => i.id === item.selected_concrete_id);
    return !inv || inv.material_type === 'concrete_service';
  });
  const totalConcreteYards = concreteServiceItems.reduce((sum, item) => sum + calcItemCost(item, inventory, project.settings || {}).volumeCY, 0);
  const roundedYards = Math.ceil(totalConcreteYards * 4) / 4;

  const firstConcreteItem = concreteServiceItems.find(i => inventory.find(inv => inv.id === i.selected_concrete_id)?.material_type === 'concrete_service');
  const firstConcreteInv = firstConcreteItem ? inventory.find(inv => inv.id === firstConcreteItem.selected_concrete_id) : null;

  const availableMixes = getConcreteMixes(firstConcreteInv);
  const availableAdmixes = getConcreteAdmixtures(firstConcreteInv);

  const mix = availableMixes.find(m => m.id === project.project_concrete_type) || availableMixes.find(m => m.id === '4000_ae');
  const mixPrice = mix ? mix.price : 201;

  const admixPrice = (project.project_concrete_admixtures || []).reduce((sum, admixId) => {
    const a = availableAdmixes.find(x => x.id === admixId);
    return sum + (a ? a.price : 0);
  }, 0);

  const ratePerYard = mixPrice + admixPrice;

  let concreteTotal = 0;
  let remainingYards = roundedYards;
  const trucksList = [];
  const fuelSurcharge = getFuelSurcharge(firstConcreteInv);

  while (remainingYards > 0) {
    const truckYards = Math.min(remainingYards, 9);
    remainingYards -= truckYards;

    // Round up to next quarter yard for cost calculation
    const roundedTruckYards = Math.ceil(truckYards * 4) / 4;

    const smallOrderFee = getSmallLoadFee(roundedTruckYards, firstConcreteInv);
    const fuelFee = fuelSurcharge;

    const truckCost = (roundedTruckYards * ratePerYard) + smallOrderFee + fuelFee;
    trucksList.push({ yards: truckYards, roundedYards: roundedTruckYards, cost: truckCost, smallOrderFee, fuelFee });
    concreteTotal += truckCost;
  }

  const newSignLocationsCount = items.filter(i => i.is_new_sign_location).length;
  const additionalStopsCost = newSignLocationsCount * 100;
  concreteTotal += additionalStopsCost;

  return { concreteTotal, roundedYards, ratePerYard, trucksList, additionalStopsCost, availableMixes, availableAdmixes };
};

// Ported verbatim from SignEstimate Pro (src/utils/wallCalculator.js).
// Do not re-derive this math — outer wall + optional internal (fill) wall
// brick counts, mortar bags, labor and totals.

export function calcWallCosts({ wall, wallShape, wallMaterial, internalMaterial, includeInternalWall, wallHeightInches, internalWallHeightInches, mortarGapInches, internalMortarGapInches, settings }) {
  if (!wallShape || !wallMaterial || !wallShape.segments) return null;

  const isConcrete = wallMaterial.wall_material_subtype === 'concrete';
  const unitL = wallMaterial.wall_unit_length_inches || 8;
  const unitW = wallMaterial.wall_unit_width_inches || 4;
  const unitH = wallMaterial.wall_unit_height_inches || 2.25;
  const mortar = isConcrete ? 0 : mortarGapInches;
  const courseH = unitH + mortar;
  const numCourses = wallHeightInches / courseH;
  const brickPitch = unitL + (isConcrete ? 0 : mortar);

  const totalLinearInches = wallShape.segments.reduce((s, seg) => s + seg.length, 0);

  const numCoursesRounded = Math.ceil(numCourses);
  let totalBricks = 0;
  wallShape.segments.forEach(seg => {
    const bricksThisCourse = Math.ceil(seg.length / brickPitch);
    totalBricks += bricksThisCourse * numCoursesRounded;
  });

  const finalBricks = wallMaterial.custom_outer_material_qty !== undefined && wallMaterial.custom_outer_material_qty !== null ? wallMaterial.custom_outer_material_qty : totalBricks;
  const materialCost = finalBricks * (wallMaterial.custom_cost_per_unit !== undefined && wallMaterial.custom_cost_per_unit !== null ? wallMaterial.custom_cost_per_unit : (wallMaterial.cost_per_unit || 0));

  const surfaceAreaSqFtSingleSide = (totalLinearInches * wallHeightInches) / 144;

  let mortarCost = 0;
  let mortarBags = 0;
  if (!isConcrete) {
    const surfaceAreaSqFtMortar = surfaceAreaSqFtSingleSide * 2;
    mortarBags = Math.ceil(surfaceAreaSqFtMortar / 30);
    const finalMortarBags = wallMaterial.custom_outer_mortar_qty !== undefined && wallMaterial.custom_outer_mortar_qty !== null ? wallMaterial.custom_outer_mortar_qty : mortarBags;
    const mortarCostPerBag = parseFloat(settings?.wall_mortar_cost_per_bag || 10);
    const finalMortarRate = wallMaterial.custom_outer_mortar_rate !== undefined && wallMaterial.custom_outer_mortar_rate !== null ? wallMaterial.custom_outer_mortar_rate : mortarCostPerBag;
    mortarCost = finalMortarBags * finalMortarRate;
  }

  const laborRatePerSqFt = wallMaterial.custom_outer_labor_rate !== undefined && wallMaterial.custom_outer_labor_rate !== null ? wallMaterial.custom_outer_labor_rate : parseFloat(settings?.wall_labor_rate || 45);
  const minCharge = parseFloat(settings?.wall_minimum_charge || 150);

  let laborCost = surfaceAreaSqFtSingleSide * laborRatePerSqFt;
  if (laborCost < minCharge) {
    laborCost = minCharge;
  }

  const laborHours = finalBricks / (parseFloat(settings?.wall_labor_bricks_per_hour || 50));

  // --- Internal Wall Calculation ---
  let internalTotalBricks = 0;
  let internalMaterialCost = 0;
  let internalMortarCost = 0;
  let internalLaborCost = 0;
  let internalLaborHours = 0;
  let internalTotalLinearInches = 0;

  if (includeInternalWall && internalMaterial) {
    const intIsConcrete = internalMaterial.wall_material_subtype === 'concrete';
    const intUnitL = internalMaterial.wall_unit_length_inches || 8;
    const intUnitW = internalMaterial.wall_unit_width_inches || 4;
    const intUnitH = internalMaterial.wall_unit_height_inches || 2.25;
    const intMortar = intIsConcrete ? 0 : (internalMortarGapInches || 0.375);
    const intCourseH = intUnitH + intMortar;
    const intNumCourses = Math.ceil(internalWallHeightInches / intCourseH);
    const intBrickPitch = intUnitL + intMortar;

    const isClosed = wallShape.closed !== false;
    const lengthReduction = isClosed ? (unitW + intUnitW) : 0;

    wallShape.segments.forEach(seg => {
      const innerSegLength = Math.max(0, seg.length - lengthReduction);
      internalTotalLinearInches += innerSegLength;

      const bricksThisCourse = Math.ceil(innerSegLength / intBrickPitch);
      internalTotalBricks += bricksThisCourse * intNumCourses;
    });

    const finalInternalBricks = wall.custom_internal_material_qty !== undefined && wall.custom_internal_material_qty !== null ? wall.custom_internal_material_qty : internalTotalBricks;
    internalMaterialCost = finalInternalBricks * (wall.custom_internal_material_cost_per_unit !== undefined && wall.custom_internal_material_cost_per_unit !== null ? wall.custom_internal_material_cost_per_unit : (internalMaterial.cost_per_unit || 0));

    const intSurfaceAreaSqFtSingleSide = (internalTotalLinearInches * internalWallHeightInches) / 144;

    let internalMortarBags = 0;
    if (!intIsConcrete) {
      const intSurfaceAreaSqFtMortar = intSurfaceAreaSqFtSingleSide * 2;
      internalMortarBags = Math.ceil(intSurfaceAreaSqFtMortar / 30);
      const finalInternalMortarBags = wall.custom_internal_mortar_qty !== undefined && wall.custom_internal_mortar_qty !== null ? wall.custom_internal_mortar_qty : internalMortarBags;
      const internalMortarCostPerBag = parseFloat(settings?.wall_mortar_cost_per_bag || 10);
      const finalInternalMortarRate = wall.custom_internal_mortar_rate !== undefined && wall.custom_internal_mortar_rate !== null ? wall.custom_internal_mortar_rate : internalMortarCostPerBag;
      internalMortarCost = finalInternalMortarBags * finalInternalMortarRate;
    }

    const internalLaborRatePerSqFt = wall.custom_internal_labor_rate !== undefined && wall.custom_internal_labor_rate !== null ? wall.custom_internal_labor_rate : parseFloat(settings?.wall_labor_rate || 45);
    internalLaborCost = intSurfaceAreaSqFtSingleSide * internalLaborRatePerSqFt;
    internalLaborHours = finalInternalBricks / (parseFloat(settings?.wall_labor_bricks_per_hour || 50));
  }

  return {
    totalBricks,
    finalBricks,
    materialCost,
    mortarBags,
    finalMortarBags: !isConcrete ? (wallMaterial.custom_outer_mortar_qty !== undefined && wallMaterial.custom_outer_mortar_qty !== null ? wallMaterial.custom_outer_mortar_qty : mortarBags) : 0,
    mortarCost,
    laborHours,
    laborRatePerSqFt,
    laborCost,
    totalCost: materialCost + mortarCost + laborCost + internalMaterialCost + internalMortarCost + internalLaborCost,
    totalLinearInches,
    numCourses,
    internalTotalBricks,
    internalMaterialCost,
    internalMortarBags: includeInternalWall && internalMaterial && internalMaterial.wall_material_subtype !== 'concrete' ? Math.ceil(((internalTotalLinearInches * internalWallHeightInches) / 144) * 2 / 30) : 0,
    internalMortarCost,
    internalLaborCost,
    internalLaborHours
  };
}

// Runs the legacy wall math for every wall on a FoundationProject.
export function calcWalls(project, inventory, settings = {}) {
  const find = (id) => inventory.find((i) => i.id === id);
  return (project.walls || []).map((wall) => {
    const wallMaterial = find(wall.materialId);
    const internalMaterial = find(wall.internalMaterialId);
    if (!wallMaterial || (wall.includeInternalWall && !internalMaterial)) {
      // Keep one coherent saved wall snapshot, rather than mixing a new outer
      // wall price with a silently omitted internal wall.
      return { ...wall, calculatedCosts: { ...(wall.calculatedCosts || {}) } };
    }
    const costs =
      calcWallCosts({
        wall,
        wallShape: wall.shape,
        wallMaterial,
        internalMaterial,
        includeInternalWall: wall.includeInternalWall,
        wallHeightInches: wall.heightInches || 24,
        internalWallHeightInches: wall.internalWallHeightInches || wall.heightInches || 24,
        mortarGapInches: wall.mortarGapInches ?? 0.375,
        internalMortarGapInches: wall.internalMortarGapInches ?? 0.375,
        settings,
      }) || {};
    return {
      ...wall,
      calculatedCosts: {
        totalBricks: costs.finalBricks || 0,
        materialCost: costs.materialCost || 0,
        mortarCost: costs.mortarCost || 0,
        laborHours: costs.laborHours || 0,
        laborCost: costs.laborCost || 0,
        totalCost: costs.totalCost || 0,
        totalLinearInches: costs.totalLinearInches || 0,
        numCourses: costs.numCourses || 0,
        internalTotalBricks: costs.internalTotalBricks || 0,
        internalMaterialCost: costs.internalMaterialCost || 0,
        internalMortarCost: costs.internalMortarCost || 0,
        internalLaborCost: costs.internalLaborCost || 0,
        internalLaborHours: costs.internalLaborHours || 0,
      },
    };
  });
}

// Pole + pole-painting math — ported VERBATIM from SignEstimate Pro
// (NewFoundationEstimate.jsx: polesTotal / calcPolePaintingCost /
//  getPolePaintingSizeMultiplier). Poles are PROJECT-level, not per foundation item.

const setting = (settings, key, def) => parseFloat(settings?.[key] || def);

const getPolePaintingSizeMultiplier = (inv, settings) => {
  const w = inv?.pole_width_inches || 6;
  if (w >= 12) return setting(settings, "pole_paint_size_multiplier_12in", 2.0);
  if (w >= 10) return setting(settings, "pole_paint_size_multiplier_10in", 1.75);
  if (w >= 8) return setting(settings, "pole_paint_size_multiplier_8in", 1.5);
  if (w >= 6) return setting(settings, "pole_paint_size_multiplier_6in", 1.25);
  return setting(settings, "pole_paint_size_multiplier_4in", 1.0);
};

export const calcPolePaintingCost = (p, inv, settings) => {
  if (!p.include_pole_painting || !inv) return 0;
  // Total pole length = height above ground + depth in ground.
  const heightFt = ((p.height_inches || 0) + (p.y_offset_inches || 0)) / 12;
  const paintCostPerLf = setting(settings, "pole_paint_cost_per_lf", 3.5);
  const paintLaborPerLf = setting(settings, "pole_paint_labor_per_lf", 2.5);
  const sizeMult = getPolePaintingSizeMultiplier(inv, settings);
  return heightFt * (paintCostPerLf + paintLaborPerLf) * sizeMult;
};

export function calcPoles(poles = [], inventory = [], settings = {}) {
  return (poles || []).map((p) => {
    const inv = inventory.find((i) => i.id === p.pole_id);
    // Preserve the last saved amounts, not a fabricated free pole. The project
    // availability gate prevents these historical values becoming a new quote.
    if (!inv) return { ...p };

    const totalPoleInches = (p.height_inches || 0) + (p.y_offset_inches || 0);
    let poleCost;
    if (inv.pole_pricing_mode === "stock_price") {
      const stockLen = (inv.pole_stock_length_ft || 20) * 12;
      const pieces = Math.ceil(totalPoleInches / stockLen);
      const rate = typeof p.custom_cost_per_unit === "number" ? p.custom_cost_per_unit : inv.pole_stock_price || 0;
      poleCost = pieces * rate;
    } else {
      const rate = typeof p.custom_cost_per_unit === "number" ? p.custom_cost_per_unit : inv.cost_per_unit || 0;
      poleCost = (totalPoleInches / 12) * rate;
    }

    const paintingCost = calcPolePaintingCost(p, inv, settings);

    return {
      ...p,
      pole_name: inv.material_name || "",
      pole_cost: poleCost,
      pole_painting_cost: paintingCost,
      total_cost: poleCost + paintingCost,
    };
  });
}

// Wall cap pricing — ported from SignEstimate Pro (WallCapsTab.jsx).
// A cut cap piece is always charged at FULL stock price; cuts do not reduce price.
const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : 0);

export function calcWallCaps(wallCaps = [], inventory = []) {
  const caps = (wallCaps || []).map((cap) => {
    const inv = inventory.find((i) => i.id === cap.cap_inventory_id);
    if (!inv) return { ...cap };
    return {
      ...cap,
      cap_name: inv?.material_name || "",
      stock_length_inches: num(inv?.cap_stock_length_inches),
      cost: num(inv?.cap_stock_price),
    };
  });

  const byInventory = Object.values(
    caps.reduce((acc, c) => {
      if (!c.cap_inventory_id) return acc;
      acc[c.cap_inventory_id] = acc[c.cap_inventory_id] || {
        id: c.cap_inventory_id,
        name: c.cap_name,
        qty: 0,
        cost: 0,
      };
      acc[c.cap_inventory_id].qty += 1;
      acc[c.cap_inventory_id].cost += num(c.cost);
      return acc;
    }, {})
  );

  return { caps, byInventory, total: caps.reduce((s, c) => s + num(c.cost), 0) };
}

const num = (value, fallback = 0) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
};
const assigned = value => (typeof value === "string" && value.trim() !== "")
  || (typeof value === "number" && Number.isFinite(value));

// Preserve the original calculator's storage precedence, including empty maps.
export function resolveFoundationEquipment(entry = {}, inventory = [], index = 0) {
  const source = entry || {};
  const equipment = inventory.find(row => row.id === source.equipment_id);
  let attachmentMode = "none";
  let attachmentRows = [];
  if (source.attachments?.length) {
    attachmentMode = "normalized";
    attachmentRows = source.attachments.map((row, rowIndex) => {
      const id = row.id || row.inventory_id;
      return {
        id, quantity: row.qty || 1, sourceRecord: row, rowIndex, field: "attachments",
        inventory: inventory.find(item => item.id === id),
      };
    });
  } else if (source.attachment_counts) {
    attachmentMode = "counts";
    attachmentRows = Object.entries(source.attachment_counts).map(([id, quantity], rowIndex) => ({
      id, quantity: num(quantity), rowIndex, field: "attachment_counts",
      inventory: inventory.find(item => item.id === id && item.material_type === "attachment"),
    }));
  } else if (source.attachment_ids?.length) {
    attachmentMode = "legacy_ids";
    attachmentRows = source.attachment_ids.map((id, rowIndex) => ({
      id, quantity: 1, rowIndex, field: "attachment_ids",
      inventory: inventory.find(item => item.id === id && item.material_type === "attachment"),
    }));
  }
  const subAttachmentRows = Object.entries(source.sub_attachment_counts || {}).map(([id, quantity], rowIndex) => ({
    id, quantity: num(quantity), rowIndex, field: "sub_attachment_counts",
    inventory: inventory.find(item => item.id === id && item.material_type === "sub_attachment"),
  }));
  const issues = [];
  const check = (id, record, kind, field) => {
    if (assigned(id) && record) return;
    const hasSelection = assigned(id);
    issues.push({
      kind, index, componentId: source.component_id ?? source._id ?? null, field,
      inventoryId: hasSelection ? id : null,
      code: hasSelection ? "catalog_item_unavailable" : "catalog_item_unassigned",
      message: `Equipment ${index + 1}: ${hasSelection ? `${kind.replaceAll("_", " ")} ${String(id)} is unavailable` : `select a catalog ${kind.replaceAll("_", " ")}`}.`,
    });
  };
  check(source.equipment_id, equipment, "equipment", "equipment_id");
  for (const row of attachmentRows) {
    if (attachmentMode === "normalized" || row.quantity !== 0) {
      check(row.id, row.inventory, "attachment", row.field);
    }
  }
  for (const row of subAttachmentRows) {
    if (row.quantity !== 0) check(row.id, row.inventory, "sub_attachment", row.field);
  }
  return { equipment, attachmentMode, attachmentRows, subAttachmentRows, issues };
}

export function foundationEquipmentCatalogIssues(entries = [], inventory = []) {
  return entries.flatMap((entry, index) => resolveFoundationEquipment(entry, inventory, index).issues);
}

// Migration happens only on an explicit edit; viewing a legacy row is pure.
export function setFoundationEquipmentCount(entry, { kind, id, quantity }) {
  if (kind !== "attachment" && kind !== "sub_attachment") throw new Error("Unknown equipment selection kind.");
  if (!assigned(id)) throw new Error("Select a catalog item before changing its quantity.");
  if (typeof quantity !== "number" || !Number.isInteger(quantity) || quantity < 0) {
    throw new Error("Attachment quantities must be nonnegative whole numbers.");
  }
  const source = entry || {};
  if (kind === "attachment" && source.attachments?.length) {
    const matches = source.attachments.filter(row => (row.id || row.inventory_id) === id);
    if (matches.length > 1 && quantity !== 0) {
      throw new Error("Duplicate attachment references require review. Remove the duplicates and add one selection.");
    }
    let attachments = source.attachments.filter(row => (row.id || row.inventory_id) !== id);
    if (quantity > 0) {
      if (matches.length) {
        attachments = source.attachments.map(row => (row.id || row.inventory_id) === id ? { ...row, qty: quantity } : row);
      } else {
        attachments = [...attachments, { id, qty: quantity }];
      }
    }
    // Do not resurrect ignored legacy charges when the final normalized row goes.
    return { ...source, attachments, attachment_counts: {}, attachment_ids: [] };
  }
  const field = kind === "sub_attachment" ? "sub_attachment_counts" : "attachment_counts";
  const raw = source[field];
  if (raw && (typeof raw !== "object" || Array.isArray(raw))) {
    throw new Error("This legacy quantity map needs review before editing.");
  }
  const counts = new Map(Object.entries(raw || {}));
  if (kind === "attachment" && !raw) {
    for (const legacyId of source.attachment_ids || []) {
      if (typeof legacyId !== "string") throw new Error("Legacy numeric attachment IDs need reassignment before editing.");
      counts.set(legacyId, (counts.get(legacyId) || 0) + 1);
    }
  }
  if (typeof id !== "string") throw new Error("Legacy numeric attachment IDs need reassignment before editing.");
  if (quantity === 0) counts.delete(id);
  else counts.set(id, quantity);
  const next = { ...source, [field]: Object.fromEntries(counts) };
  return kind === "attachment" ? { ...next, attachments: [], attachment_ids: [] } : next;
}

import { foundationEquipmentCatalogIssues } from "./foundationEquipmentBindings";

export function foundationItemCatalogIssues(item, inventory = [], index = 0) {
  const issues = [];
  const add = (field, id, label, code = "catalog_item_unavailable") => issues.push({
    kind: "foundation", index, componentId: item.component_id ?? null, field,
    inventoryId: id ?? null, code,
    message: `Foundation ${index + 1}: ${label} is unavailable.`,
  });
  const selected = id => id !== undefined && id !== null && id !== "";
  const check = (field, types, label) => {
    const id = item[field];
    if (!selected(id)) return;
    const row = inventory.find(record => record.id === id);
    if (!row || !types.includes(row.material_type)) {
      add(field, id, label, row ? "catalog_item_type_mismatch" : "catalog_item_unavailable");
    }
  };
  check("selected_concrete_id", ["bagged_concrete", "concrete_service"], "selected concrete catalog material");
  if (item.include_forming) check("selected_forming_id", ["forming_material"], "selected forming catalog material");
  const manualRebar = hasFoundationCostSnapshot(item.custom_rebar_cost_per_ft) && item.custom_rebar_cost_per_ft >= 0;
  if (item.include_rebar && !manualRebar) {
    const field = item.foundation_type === "spread_foot" ? "rebar_size" : "pillar_rebar_size";
    const size = field === "rebar_size" ? item.rebar_size : item.pillar_rebar_size || "#4";
    if (!inventory.some(row => row.material_type === "rebar" && row.rebar_size === size)) {
      add(field, null, `rebar catalog size ${size || "(not selected)"}`, size ? "catalog_item_unavailable" : "catalog_item_unassigned");
    }
  }
  return issues;
}

// Availability only: this does not validate rates, geometry, or engineering.
export function foundationAssemblyCatalogIssues(project, inventory = []) {
  const available = new Set(inventory.map((row) => row.id));
  const issues = [];
  const check = (row, index, kind, field, label) => {
    const id = row[field];
    const assigned = (typeof id === "string" && id.trim() !== "")
      || (typeof id === "number" && Number.isFinite(id));
    if (assigned && available.has(id)) return;
    issues.push({
      kind,
      index,
      componentId: row.component_id ?? row.id ?? null,
      field,
      inventoryId: assigned ? id : null,
      code: assigned ? "catalog_item_unavailable" : "catalog_item_unassigned",
      message: `${label} ${index + 1}: ${assigned ? "selected catalog material is unavailable" : "select a catalog material"}.`,
    });
  };
  for (const [index, pole] of (project?.poles || []).entries()) {
    check(pole, index, "pole", "pole_id", "Pole");
  }
  for (const [index, cap] of (project?.wall_caps || []).entries()) {
    check(cap, index, "wall_cap", "cap_inventory_id", "Wall cap");
  }
  for (const [index, wall] of (project?.walls || []).entries()) {
    check(wall, index, "wall", "materialId", "Wall");
    if (wall.includeInternalWall) {
      check(wall, index, "internal_wall", "internalMaterialId", "Internal wall");
    }
  }
  return [
    ...issues,
    ...(project?.items || []).flatMap((item, index) => foundationItemCatalogIssues(item, inventory, index)),
    ...foundationEquipmentCatalogIssues(project?.selected_equipment || [], inventory),
  ];
}

// A missing snapshot is not evidence of a free material.
export function hasFoundationCostSnapshot(value) {
  return typeof value === "number" && Number.isFinite(value);
}

const inputNumber = value => {
  if (typeof value === "number") return Number.isFinite(value) ? value : null;
  if (typeof value !== "string" || !/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(value.trim())) return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
};

const positiveWholeNumber = value => {
  const number = inputNumber(value);
  const whole = typeof value !== "string" || /^[+-]?\d+(?:\.0*)?$/.test(value.trim());
  return whole && Number.isSafeInteger(number) && number > 0;
};

export function foundationItemInputIssues(item, index = 0) {
  const record = item ?? {};
  const issues = [];
  const add = (field, code, message) => issues.push({
    kind: "foundation", index, componentId: record.component_id ?? null, field, code,
    message: `Foundation ${index + 1}: ${message}`,
  });
  const type = record.foundation_type;
  if (type !== "spread_foot" && type !== "pillar") {
    add("foundation_type", "foundation_type_invalid", "select Spread Footing or Pillar / Caisson.");
  }
  const count = record.quantity ?? 1;
  const quantity = inputNumber(count);
  if (!positiveWholeNumber(count)) {
    add("quantity", "foundation_quantity_invalid", "quantity must be a positive whole number within the supported range.");
  }
  const fields = type === "spread_foot"
    ? [["length_inches", "length"], ["width_inches", "width"], ["depth_inches", "depth"]]
    : type === "pillar" ? [["diameter", "diameter"], ["depth_inches", "depth"]] : [];
  const dimensions = {};
  for (const [field, label] of fields) {
    const value = inputNumber(record[field]);
    dimensions[field] = value;
    if (value === null || value <= 0) {
      add(field, "foundation_dimension_invalid", `${label} (inches) must be a finite positive number.`);
    }
  }
  if (!issues.length) {
    const depth = dimensions.depth_inches / 12;
    const radius = dimensions.diameter / 24;
    const volume = type === "spread_foot"
      ? ((dimensions.length_inches / 12) * (dimensions.width_inches / 12) * depth) / 27 * quantity
      : (Math.PI * radius * radius * depth) / 27 * quantity;
    // This is numeric-range validation, not a structural design or engineering minimum.
    if (!Number.isFinite(volume) || volume <= 0) {
      add("dimensions", "foundation_volume_out_of_range", "dimensions and quantity cannot produce a finite positive volume in the supported calculation range.");
    }
  }
  if (record.include_rebar) {
    const optional = (field, code, label, valid) => {
      const value = record[field];
      if (value !== undefined && value !== null && !valid(value)) add(field, code, label);
    };
    const positive = value => {
      const number = inputNumber(value);
      return number !== null && number > 0;
    };
    const whole = (field, label) => optional(field, "foundation_rebar_count_invalid",
      `${label} must be a positive whole number within the supported range.`, positiveWholeNumber);
    if (type === "spread_foot") {
      for (const [field, label] of [["rebar_spacing_length", "length"], ["rebar_spacing_width", "width"]]) {
        optional(field, "foundation_rebar_spacing_invalid",
          `rebar spacing ${label} (inches) must be a finite positive number.`, positive);
      }
      whole("rebar_layers", "Rebar mat count");
    } else if (type === "pillar") {
      whole("pillar_rebar_layers", "Hoop count");
      whole("pillar_vertical_rebar_count", "Longitudinal bar count");
      optional("pillar_rebar_hoop_diameter", "foundation_rebar_diameter_invalid",
        "hoop diameter (inches) must be finite, positive and no greater than the foundation diameter.",
        value => positive(value) && (dimensions.diameter === null || dimensions.diameter <= 0 || inputNumber(value) <= dimensions.diameter));
    }
  }
  return issues;
}

export function foundationProjectInputIssues(project) {
  const items = project?.items ?? [];
  if (!Array.isArray(items)) throw new Error("Foundation items must be an array.");
  return items.flatMap((item, index) => foundationItemInputIssues(item, index));
}

// Landscape materials for the Signage & Landscape designer.
// Each cell on the grid is one square foot by default.
export const LANDSCAPE_MATERIALS = [
  { key: "dirt", label: "Dirt (Eraser)", color: "#a1866f", cost_per_sqft: 0 },
  { key: "grass", label: "Grass", color: "#4ade80", cost_per_sqft: 0.75 },
  { key: "concrete", label: "Concrete", color: "#cbd5e1", cost_per_sqft: 8 },
  { key: "asphalt", label: "Asphalt", color: "#475569", cost_per_sqft: 5 },
  { key: "gravel", label: "Gravel", color: "#94a3b8", cost_per_sqft: 2.25 },
  { key: "sand", label: "Sand", color: "#fcd34d", cost_per_sqft: 1.75 },
  { key: "mulch", label: "Mulch", color: "#92400e", cost_per_sqft: 1.25 },
  { key: "wood_decking", label: "Wood Decking", color: "#d97706", cost_per_sqft: 14 },
  { key: "water", label: "Water", color: "#38bdf8", cost_per_sqft: 6 },
];

export const materialByKey = (key) => LANDSCAPE_MATERIALS.find((m) => m.key === key);

export const GRID_COLS = 24;
export const GRID_ROWS = 16;

export const landscapeSummary = (landscape) => {
  const cells = landscape?.cells || {};
  const sqftPerCell = Math.pow((landscape?.cell_size_inches || 12) / 12, 2);
  const rows = {};
  Object.values(cells).forEach((key) => {
    if (!key || key === "dirt") return;
    rows[key] = (rows[key] || 0) + sqftPerCell;
  });
  const lines = Object.entries(rows).map(([key, sqft]) => {
    const mat = materialByKey(key);
    return {
      key,
      label: mat?.label || key,
      color: mat?.color || "#999",
      sqft,
      cost: sqft * (mat?.cost_per_sqft || 0),
    };
  });
  return { lines, total: lines.reduce((s, l) => s + l.cost, 0) };
};

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  if (a !== null && a !== undefined && a !== "" && b !== null && b !== undefined && b !== "") {
    if (Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
      return Math.abs(Number(a) - Number(b)) <= 0.000001;
    }
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

function isEntityNotFoundError(error) {
  const status = Number(error?.status || error?.response?.status || error?.response?.statusCode || error?.data?.status || 0);
  if (status === 404) return true;
  const message = String(
    error?.message ||
    error?.response?.data?.message ||
    error?.response?.data?.error ||
    error?.data?.message ||
    error?.data?.error ||
    ""
  ).toLowerCase();
  return message.includes("not found") || message.includes("does not exist");
}

export function expectedBuilderEntityFields(record = {}, nextFields = {}) {
  return Object.fromEntries(
    Object.keys(nextFields || {}).map((field) => [field, record?.[field]])
  );
}

export async function replaceBuilderEntityFieldsIfUnchanged({
  entity,
  id,
  expectedUpdatedAt = "",
  expectedFields,
  nextFields,
  guardFields = {},
  label = "Builder record",
  maxAttempts = 3,
} = {}) {
  const recordId = String(id || "").trim();
  const expectedVersion = String(expectedUpdatedAt || "").trim();
  const expected = expectedFields && typeof expectedFields === "object" && !Array.isArray(expectedFields) ? expectedFields : null;
  const desired = nextFields && typeof nextFields === "object" && !Array.isArray(nextFields) ? nextFields : null;
  const guards = guardFields && typeof guardFields === "object" && !Array.isArray(guardFields) ? guardFields : {};
  const fieldNames = desired ? Object.keys(desired) : [];
  if (!recordId || !expected || !desired || fieldNames.length === 0 || typeof entity?.get !== "function" || typeof entity?.updateMany !== "function") {
    throw new Error(`${label} could not initialize its concurrency-safe update.`);
  }
  for (const fieldName of fieldNames) {
    if (!Object.prototype.hasOwnProperty.call(expected, fieldName)) {
      throw new Error(`${label} is missing the loaded baseline for ${fieldName}.`);
    }
  }

  const attempts = Math.max(1, Math.min(5, Number(maxAttempts) || 3));
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    const current = await entity.get(recordId);
    if (!current?.id) throw new Error(`${label} could not be re-read before saving.`);

    for (const [fieldName, value] of Object.entries(guards)) {
      if (!sameValue(current[fieldName], value)) {
        throw new Error(`${label} changed in another session (${fieldName}). Reload before saving.`);
      }
    }

    const alreadyDesired = fieldNames.every((fieldName) => sameValue(current[fieldName], desired[fieldName]));
    if (alreadyDesired) return current;

    if (expectedVersion && String(current.updated_date || "") !== expectedVersion) {
      throw new Error(`${label} changed in another session. Reload before saving.`);
    }

    for (const fieldName of fieldNames) {
      if (!sameValue(current[fieldName], expected[fieldName]) && !sameValue(current[fieldName], desired[fieldName])) {
        throw new Error(`${label} changed in another session (${fieldName}). Reload before saving.`);
      }
    }

    const currentVersion = String(current.updated_date || "").trim();
    if (!currentVersion) throw new Error(`${label} is missing its current version. Reload before saving.`);

    let result;
    try {
      result = await entity.updateMany(
        { id: recordId, updated_date: currentVersion },
        { $set: desired },
      );
    } catch (error) {
      const afterError = await entity.get(recordId).catch(() => null);
      if (afterError && fieldNames.every((fieldName) => sameValue(afterError[fieldName], desired[fieldName]))) return afterError;
      throw error;
    }

    if (!result || typeof result.updated !== "number") {
      throw new Error(`${label} conditional-update result could not be verified.`);
    }
    if (result.updated === 1) {
      const saved = await entity.get(recordId).catch(() => null);
      if (!saved) throw new Error(`${label} was updated but could not be re-read.`);
      return saved;
    }
  }

  throw new Error(`${label} changed repeatedly while saving. Reload and try again.`);
}

export async function deleteBuilderEntityIfUnchanged({
  entity,
  record,
  guardFields = {},
  label = "Builder record",
} = {}) {
  const id = String(record?.id || "").trim();
  const updatedDate = String(record?.updated_date || "").trim();
  if (!id || !updatedDate || typeof entity?.deleteMany !== "function" || typeof entity?.get !== "function") {
    throw new Error(`${label} could not initialize its concurrency-safe delete.`);
  }
  // Caller guards can narrow the match further but must never widen it past
  // the loaded id + updated_date anchor, so they are spread first.
  const query = { ...guardFields, id, updated_date: updatedDate };
  let result;
  try {
    result = await entity.deleteMany(query);
  } catch (error) {
    let current;
    try {
      current = await entity.get(id);
    } catch (verificationError) {
      if (isEntityNotFoundError(verificationError)) {
        return { deleted: true, convergedAfterResponseLoss: true };
      }
      throw new Error(
        `${label} delete returned an error and its outcome could not be verified. ` +
        `Do not retry blindly; reload before continuing. ${verificationError?.message || ""}`.trim()
      );
    }
    if (!current) return { deleted: true, convergedAfterResponseLoss: true };
    throw error;
  }
  if (!result || typeof result.deleted !== "number") {
    throw new Error(`${label} conditional-delete result could not be verified.`);
  }
  if (result.deleted === 1) return { deleted: true };
  if (result.deleted > 1) {
    throw new Error(`${label} returned an impossible multi-record delete count.`);
  }
  let current;
  try {
    current = await entity.get(id);
  } catch (verificationError) {
    if (isEntityNotFoundError(verificationError)) {
      return { deleted: true, alreadyDeleted: true };
    }
    throw new Error(
      `${label} deletion matched no current version and the record could not be re-read. ` +
      `Do not retry blindly; reload before continuing. ${verificationError?.message || ""}`.trim()
    );
  }
  if (!current) return { deleted: true, alreadyDeleted: true };
  throw new Error(`${label} changed in another session. It was not deleted.`);
}

// Generic aliases let other estimator records reuse the same proven conditional
// persistence behavior without introducing a second concurrency implementation.
export const expectedEntityFields = expectedBuilderEntityFields;
export const replaceEntityFieldsIfUnchanged = replaceBuilderEntityFieldsIfUnchanged;
export const deleteEntityIfUnchanged = deleteBuilderEntityIfUnchanged;

import { deleteEntityIfUnchanged } from "@/components/estimator/builder/builderEntityPersistence";

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// Read-after-write grace for the post-create verify read: a create whose
// response was lost can still have landed, and an immediate empty verify
// read is not conclusive.
const VERIFY_RETRY_DELAY_MS = 700;

const canonicalRecord = (rows = []) => [...rows].sort((a, b) => {
  const aStamp = String(a?.created_date || "");
  const bStamp = String(b?.created_date || "");
  if (aStamp !== bStamp) return aStamp.localeCompare(bStamp);
  return String(a?.id || "").localeCompare(String(b?.id || ""));
})[0] || null;

function normalize(value) {
  if (Array.isArray(value)) return value.map(normalize);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalize(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  const emptyA = a === undefined || a === null || a === "";
  const emptyB = b === undefined || b === null || b === "";
  if (emptyA && emptyB) return true;
  if (!emptyA && !emptyB && Number.isFinite(Number(a)) && Number.isFinite(Number(b))) {
    return Math.abs(Number(a) - Number(b)) <= 0.000001;
  }
  // Trimmed server values must match the retry payload — backend `clean()`
  // trims most string fields on write, so a strict compare would false-negative
  // a legitimately-reused record and 409 "retry key belongs to different data".
  if (typeof a === "string" && typeof b === "string") return a.trim() === b.trim();
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b));
}

function matchesPayload(row, payload) {
  return !!row && Object.entries(payload || {}).every(([field, value]) => sameValue(row[field], value));
}

export function newCreationRequestKey(prefix = "create") {
  const token = globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`;
  return `${String(prefix || "create").trim()}:${token}`;
}

export async function ensureIdempotentEntityCreate({
  entity,
  keyField = "idempotency_key",
  key,
  data,
  label = "Record",
} = {}) {
  const cleanField = String(keyField || "").trim();
  const cleanKey = String(key || "").trim();
  if (!entity?.filter || !entity?.create || !cleanField || !cleanKey) {
    throw new Error(`${label} could not initialize its retry-safe create.`);
  }

  const payload = { ...data, [cleanField]: cleanKey };
  const load = async () => {
    const rows = await entity.filter({ [cleanField]: cleanKey });
    if (!Array.isArray(rows)) throw new Error(`${label} retry state could not be verified.`);
    return rows.filter((row) => String(row?.[cleanField] || "").trim() === cleanKey);
  };

  const existing = await load();
  if (existing.length > 1) {
    throw new Error(`${label} already has multiple records with this retry key. No row was deleted; reload and review the duplicates before continuing.`);
  }
  if (existing.length === 1) {
    if (!matchesPayload(existing[0], payload)) {
      throw new Error(`${label} retry key already belongs to a record with different data. No row was changed.`);
    }
    return existing[0];
  }

  let created = null;
  let createError = null;
  try {
    created = await entity.create(payload);
  } catch (error) {
    createError = error;
  }

  let afterCreate = null;
  let verifyError = null;
  try {
    afterCreate = await load();
  } catch (error) {
    verifyError = error;
  }
  // Read-after-write lag: a create that failed at the response layer can
  // still have landed, so an immediate empty/failed verify is not conclusive.
  // Give the write a moment and re-read once before declaring the outcome
  // unknown — a retry must resolve the existing row, never create a dup.
  if ((!Array.isArray(afterCreate) || afterCreate.length === 0) && (createError || !created?.id)) {
    await sleep(VERIFY_RETRY_DELAY_MS);
    try {
      const retryRows = await load();
      if (Array.isArray(retryRows)) afterCreate = retryRows;
    } catch (error) {
      verifyError = verifyError || error;
    }
  }
  if (!Array.isArray(afterCreate)) {
    if (created?.id && matchesPayload(created, payload)) return created;
    throw new Error(`${label} create outcome could not be verified. Do not retry blindly; reload first. ${verifyError?.message || "Recovery lookup failed."}`);
  }

  if (afterCreate.length === 1) {
    // Our create returned an id but the only visible same-key row is a
    // different record — a concurrent create landed too and ours is still
    // indexing. Fail closed instead of silently orphaning our row as a dup.
    if (created?.id && String(afterCreate[0].id) !== String(created.id)) {
      throw new Error(`${label} was created concurrently more than once. No uncertain duplicate was deleted; reload and review records with this retry key.`);
    }
    if (!matchesPayload(afterCreate[0], payload)) {
      throw new Error(`${label} retry key exists but its live data does not match this create. No row was changed or deleted.`);
    }
    return afterCreate[0];
  }

  if (afterCreate.length > 1) {
    const keep = canonicalRecord(afterCreate);
    const ours = created?.id ? afterCreate.find((row) => row.id === created.id) : null;
    if (ours && ours.id !== keep?.id && matchesPayload(ours, payload)) {
      await deleteEntityIfUnchanged({
        entity,
        record: ours,
        guardFields: { [cleanField]: cleanKey },
        label: `${label} losing retry duplicate`,
      });
      const finalRows = await load();
      if (finalRows.length === 1 && finalRows[0]?.id === keep?.id && matchesPayload(finalRows[0], payload)) {
        return finalRows[0];
      }
    }
    throw new Error(`${label} was created concurrently more than once. No uncertain duplicate was deleted; reload and review records with this retry key.`);
  }

  if (created?.id && matchesPayload(created, payload)) return created;
  if (createError) {
    throw new Error(`${label} create failed and no matching record was visible on recovery read. Do not retry blindly; reload first. ${createError?.message || ""}`.trim());
  }
  throw new Error(`${label} create response could not be verified. Do not retry blindly; reload first.`);
}

// Extracts cost lines from each module's project records and tags them
// with the proper category_key for tier-markup application.
//
// Mapping (from user's tier sheet):
//   Channel/Raceway/Capsule letter purchases  -> outsourced_fab
//   Dimensional Letter substrate (material)   -> substrates
//   Dimensional Letter paint materials        -> outsourced_fab
//   Dimensional Letter fab labor (CNC+paint)  -> inhouse_labor
//   Channel Letter install labor              -> inhouse_labor
//   Install materials/supplies (hardware)     -> outsourced_fab
//   Equipment rental (lifts)                  -> outsourced_services
//   Concrete + rebar materials                -> outsourced_fab
//   Foundation labor                          -> inhouse_labor
//   Poles                                     -> outsourced_fab
//   Foundation equipment rental               -> outsourced_services
//   Brick/stone material                      -> outsourced_fab
//   Masonry outsourced labor                  -> outsourced_services
//   Mortar + supplies                         -> outsourced_fab
//   Paint Estimator materials                 -> outsourced_fab
//   Paint Estimator labor                     -> inhouse_labor
//   Laser machine time                        -> machine_time
//   Laser labor                               -> inhouse_labor
//   Laser materials                           -> substrates
//   CNC machine time                          -> machine_time
//   CNC labor                                 -> inhouse_labor
//   CNC materials                             -> substrates
//   Metal Fab material                        -> substrates
//   Metal Fab labor                           -> inhouse_labor

const num = (v) => Number(v) || 0;

// Per-project memoization (#412): categorize output depends only on the
// project payload. A WeakMap keyed on the project object skips recompute when
// React re-renders pass the same object, and entries GC with the object.
const _catCache = new WeakMap();
const _catMemo = (p, compute) => {
  if (!p || typeof p !== "object") return compute(p);
  let byFn = _catCache.get(p);
  if (byFn && byFn.has(compute)) return byFn.get(compute);
  const out = compute(p);
  if (!byFn) { byFn = new Map(); _catCache.set(p, byFn); }
  byFn.set(compute, out);
  return out;
};

function _impl_categorizeChannelLetterProject(p) {
  if (!p) return [];
  const lines = [];

  // 1. Letter purchases - check each letter type
  (p.letter_purchases || []).forEach((lp) => {
    const isDimensional = lp.letter_type === 'dimensional_letters';
    const total = num(lp.total_cost);
    if (total <= 0) return;

    if (isDimensional && lp.fab_config) {
      // Dimensional: split into material vs labor using fab_config if present
      const matCost = num(lp.fab_config.material_cost) + num(lp.fab_config.paint_material_cost);
      const laborCost = num(lp.fab_config.cnc_labor_cost) + num(lp.fab_config.paint_labor_cost);
      if (matCost > 0) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter Material — ${lp.description || ''}`, cost: matCost, category_key: 'substrates' });
      }
      if (laborCost > 0) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter Fab Labor — ${lp.description || ''}`, cost: laborCost, category_key: 'inhouse_labor' });
      }
      const remainder = total - matCost - laborCost;
      if (remainder > 0.01) {
        lines.push({ module: 'channel_letter', label: `Dimensional Letter (other) — ${lp.description || ''}`, cost: remainder, category_key: 'substrates' });
      }
    } else if (isDimensional) {
      // Dimensional with no fab_config breakdown — categorize whole as substrates (material side)
      lines.push({ module: 'channel_letter', label: `Dimensional Letters — ${lp.description || ''}`, cost: total, category_key: 'substrates' });
    } else {
      // Channel / Raceway / Capsule / Logo = outsourced fab
      lines.push({ module: 'channel_letter', label: `Letter Purchase — ${lp.description || lp.letter_type}`, cost: total, category_key: 'outsourced_fab' });
    }
  });

  // 1b. Letter-level fees
  // Delivery doesn't apply when every product is dimensional (matches lettersCalculator)
  const onlyDimensional = (p.letter_purchases || []).length > 0 &&
    (p.letter_purchases || []).every(lp => lp.letter_type === 'dimensional_letters');
  const letterFees =
    (onlyDimensional ? 0 : num(p.letters_delivery_fee)) + num(p.letters_design_fee) +
    num(p.letters_install_supplies_fee) + num(p.letters_permitting_fee) +
    num(p.letters_other_fee);
  if (letterFees > 0) {
    lines.push({ module: 'channel_letter', label: 'Letter Fees (delivery/design/permit/etc.)', cost: letterFees, category_key: 'outsourced_fab' });
  }

  // 2. Installation labor — when a crew is assigned, personnel pricing replaces
  // the flat-rate labor (labor_cost_in_subtotal = 0), so labor is never double-counted.
  const baseLabor = p.labor_cost_in_subtotal !== undefined
    ? num(p.labor_cost_in_subtotal)
    : num(p.labor_cost);
  const installLabor = baseLabor + num(p.total_personnel_cost);
  if (installLabor > 0) {
    lines.push({ module: 'channel_letter', label: 'Installation Labor', cost: installLabor, category_key: 'inhouse_labor' });
  }

  // 3. Materials/supplies (hardware, mounting)
  const matCost = num(p.total_materials_cost) + num(p.total_supplies_cost);
  if (matCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Install Materials & Supplies', cost: matCost, category_key: 'outsourced_fab' });
  }

  // 4. Equipment rental
  const eqCost = num(p.total_equipment_cost);
  if (eqCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Equipment Rental', cost: eqCost, category_key: 'outsourced_services' });
  }

  // 5. Travel — was previously missing, so categorized lines didn't sum to the subtotal
  const travelCost = num(p.total_travel_cost);
  if (travelCost > 0) {
    lines.push({ module: 'channel_letter', label: 'Travel & Fuel', cost: travelCost, category_key: 'outsourced_services' });
  }

  return lines;
}

function _impl_categorizeFoundationProject(p) {
  if (!p) return [];
  const lines = [];
  const concrete = num(p.total_concrete_cost) + num(p.total_rebar_cost) + num(p.total_forming_materials_cost);
  if (concrete > 0) lines.push({ module: 'foundation', label: 'Concrete / Rebar / Forming Materials', cost: concrete, category_key: 'outsourced_fab' });
  const fLabor = num(p.total_labor_cost) + num(p.total_excavation_cost);
  if (fLabor > 0) lines.push({ module: 'foundation', label: 'Foundation Labor', cost: fLabor, category_key: 'inhouse_labor' });
  const poles = num(p.total_pole_cost) + num(p.total_pole_painting_cost);
  if (poles > 0) lines.push({ module: 'foundation', label: 'Poles & Pole Painting', cost: poles, category_key: 'outsourced_fab' });
  const eq = num(p.total_equipment_cost);
  if (eq > 0) lines.push({ module: 'foundation', label: 'Foundation Equipment Rental', cost: eq, category_key: 'outsourced_services' });

  // Foundation wall totals already contain their material, mortar and labor. Use
  // the calculated wall rows directly so tier pricing neither double-counts the
  // aggregate brick/fill fields nor treats masonry labor as purchased material.
  const wallMaterial = (p.walls || []).reduce((sum, wall) => {
    const costs = wall?.calculatedCosts || {};
    return sum + num(costs.materialCost) + num(costs.mortarCost) + num(costs.internalMaterialCost) + num(costs.internalMortarCost);
  }, 0);
  const wallLabor = (p.walls || []).reduce((sum, wall) => {
    const costs = wall?.calculatedCosts || {};
    return sum + num(costs.laborCost) + num(costs.internalLaborCost);
  }, 0);
  if (wallMaterial > 0) lines.push({ module: 'foundation', label: 'Brick / Wall / Mortar Materials', cost: wallMaterial, category_key: 'outsourced_fab' });
  if (wallLabor > 0) lines.push({ module: 'foundation', label: 'Masonry Labor', cost: wallLabor, category_key: 'outsourced_services' });

  const wallCaps = num(p.total_wall_cap_cost);
  if (wallCaps > 0) lines.push({ module: 'foundation', label: 'Wall Cap Materials', cost: wallCaps, category_key: 'outsourced_fab' });
  const cabinets = num(p.total_signage_cabinet_cost);
  if (cabinets > 0) lines.push({ module: 'foundation', label: 'Purchased Signage Cabinets', cost: cabinets, category_key: 'outsourced_fab' });
  const landscape = num(p.total_landscape_cost);
  if (landscape > 0) lines.push({ module: 'foundation', label: 'Landscape / Site Materials', cost: landscape, category_key: 'outsourced_fab' });
  return lines;
}

