// Adds Painted Dimensional Letters on top of the monument repaint calc.
// Pulls rates from the *Paint Estimator* settings (no new settings created).
//
// Inputs from item.repaint_config.dim_letter_paint:
//   { enabled, qty, avg_height_in, thickness_in, second_color_mask }
//
// Output (or null if not enabled):
//   {
//     letters_face_sqft, letters_returns_sqft, letters_total_sqft,
//     letters_gallons, letters_paint_cost,
//     mask_sqft, mask_material_cost, mask_machine_cost,
//     mask_weed_labor_cost, mask_apply_labor_cost,
//     mask_total_cost, mask_labor_hours,
//     letters_labor_hours, letters_total_added_cost,
//   }

const num = (v, d = 0) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : d;
};

// Mirror paint cost-per-gallon resolution used by PaintSettings.
const UNIT_FACTORS = { oz: 1/128, pint: 1/8, quart: 1/4, liter: 1/3.78541, gallon: 1 };
const costPerGallon = (cost, unit) => {
  const c = num(cost);
  const f = UNIT_FACTORS[unit] || 1;
  if (!f) return 0;
  return c / f;
};

// Liquid mixed paint $ per sqft, derived from PaintSettings mix.
const mixedPaintCostPerSqft = (s) => {
  const paintG = costPerGallon(s.paint_cost_per_unit, s.paint_unit);
  const hardG  = costPerGallon(s.hardener_cost_per_unit, s.hardener_unit);
  const redG   = costPerGallon(s.reducer_cost_per_unit, s.reducer_unit);
  const pR = num(s.paint_mix_ratio), hR = num(s.hardener_mix_ratio), rR = num(s.reducer_mix_ratio);
  const parts = pR + hR + rR;
  if (!parts) return 0;
  const costPerGalMixed = (paintG * pR + hardG * hR + redG * rR) / parts;
  const coverage = num(s.mixed_paint_coverage_sqft_per_gallon, 350) || 350;
  return costPerGalMixed / coverage;
};

// Estimate sqft of paintable area on a single dimensional letter:
//   face = h × (h × perimeterFactor / 4)  ≈ approximated using h² for stroke-based letters
// We use the same approximation as the Paint Estimator's letter math:
//   letter face area ≈ h² × 0.55 (typical sans serif), but to stay simple,
//   we expose a knob: face_factor = 0.55 (face vs bounding box).
// Return walls = letter perimeter × thickness.
// Letter perimeter = h × letter_perimeter_factor (from Paint Settings).
export const computeDimLetterPaint = (cfg, settings) => {
  const dl = cfg?.dim_letter_paint;
  if (!dl?.enabled) return null;

  const qty = Math.max(0, num(dl.qty));
  if (qty <= 0) return null;
  const hIn = Math.max(0, num(dl.avg_height_in));
  const tIn = Math.max(0, num(dl.thickness_in));
  if (hIn <= 0) return null;

  const perimFactor = num(settings.letter_perimeter_factor, 3.5) || 3.5;
  const FACE_FACTOR = 0.55; // sans-serif stroke ratio

  // Per-letter areas in square inches
  const facePerLetterIn2 = hIn * hIn * FACE_FACTOR;
  const returnsPerLetterIn2 = (hIn * perimFactor) * tIn;

  // Convert to sqft × qty
  const SQIN_PER_SQFT = 144;
  const letters_face_sqft = (facePerLetterIn2 * qty) / SQIN_PER_SQFT;
  const letters_returns_sqft = (returnsPerLetterIn2 * qty) / SQIN_PER_SQFT;
  const letters_total_sqft = letters_face_sqft + letters_returns_sqft;

  // Paint material cost
  const liquid$PerSqft = mixedPaintCostPerSqft(settings);
  const wasteMult = num(settings.paint_waste_multiplier, 1.25) || 1.25;
  const letters_paint_cost = letters_total_sqft * liquid$PerSqft * wasteMult;
  const coverage = num(settings.mixed_paint_coverage_sqft_per_gallon, 350) || 350;
  const letters_gallons = (letters_total_sqft * wasteMult) / coverage;

  // Labor: use Paint Settings base hours/sqft + small-letter prep multiplier when applicable
  const basePerSqft = num(settings.base_labor_hours_per_sqft, 0.05);
  let prepMult = num(settings.lettering_normal_prep_multiplier, 1.0) || 1.0;
  if (hIn <= 4)       prepMult = num(settings.lettering_extra_small_prep_multiplier, 1.5);
  else if (hIn <= 8)  prepMult = num(settings.lettering_small_prep_multiplier, 1.3);
  else if (hIn <= 12) prepMult = num(settings.lettering_normal_prep_multiplier, 1.0);
  else if (hIn <= 20) prepMult = num(settings.lettering_medium_prep_multiplier, 0.9);
  else if (hIn <= 30) prepMult = num(settings.lettering_large_prep_multiplier, 0.8);
  else                prepMult = num(settings.lettering_extra_large_prep_multiplier, 0.7);
  const letters_labor_hours = letters_total_sqft * basePerSqft * prepMult;

  // Paint Mask (only when the second color requires masking)
  const usingMask = dl.second_color_mask === "paint_mask";
  let mask_sqft = 0, mask_material_cost = 0, mask_machine_cost = 0;
  let mask_weed_labor_cost = 0, mask_apply_labor_cost = 0, mask_labor_hours = 0;
  if (usingMask) {
    // Mask covers the face area only (returns aren't typically masked for a 2nd color)
    mask_sqft = letters_face_sqft;
    const matRate    = num(settings.paint_mask_rate_per_sqft);
    const machineRate= num(settings.paint_mask_machine_cutting_rate_per_sqft);
    const weedRate   = num(settings.paint_mask_cutting_labor_rate_per_sqft);
    const applyRate  = num(settings.paint_mask_application_labor_rate_per_sqft);
    const laborRate  = num(settings.default_labor_rate, 60) || 60;

    mask_material_cost = mask_sqft * matRate;
    mask_machine_cost  = mask_sqft * machineRate;
    mask_weed_labor_cost  = mask_sqft * weedRate;
    mask_apply_labor_cost = mask_sqft * applyRate;
    // Convert mask labor $ back into hours so it rolls into the maintenance labor pool
    const mask_labor_cost = mask_weed_labor_cost + mask_apply_labor_cost;
    mask_labor_hours = laborRate > 0 ? (mask_labor_cost / laborRate) : 0;

    // For a 2nd color the letters get painted twice on the face (base + accent),
    // double the face paint quantity.
    const secondColorExtraPaint = letters_face_sqft * liquid$PerSqft * wasteMult;
    // Add to letters_paint_cost
    // (mutate locally so the return value matches)
    // eslint-disable-next-line no-param-reassign
    return finalize({
      letters_face_sqft, letters_returns_sqft, letters_total_sqft,
      letters_gallons: letters_gallons + (letters_face_sqft * wasteMult) / coverage,
      letters_paint_cost: letters_paint_cost + secondColorExtraPaint,
      mask_sqft, mask_material_cost, mask_machine_cost,
      mask_weed_labor_cost, mask_apply_labor_cost,
      mask_labor_hours, letters_labor_hours,
    });
  }

  return finalize({
    letters_face_sqft, letters_returns_sqft, letters_total_sqft,
    letters_gallons, letters_paint_cost,
    mask_sqft: 0, mask_material_cost: 0, mask_machine_cost: 0,
    mask_weed_labor_cost: 0, mask_apply_labor_cost: 0,
    mask_labor_hours: 0, letters_labor_hours,
  });
};

const finalize = (r) => {
  const mask_total_cost =
    r.mask_material_cost + r.mask_machine_cost + r.mask_weed_labor_cost + r.mask_apply_labor_cost;
  const letters_total_added_cost = r.letters_paint_cost + mask_total_cost;
  return { ...r, mask_total_cost, letters_total_added_cost };
};

// Pure helpers for the Repaint action.
// Given an item's repaint_config + the Settings entity, compute:
//   - paintable square footage (face + retainers/returns based on mode)
//   - feature & condition multipliers
//   - estimated paint quantity (gallons) and paint material cost
//   - prep+paint labor hours (sqft / sqft-per-hour, multiplied by feature & condition)
//
// Returns null when the item is not a monument-sign repaint with a config.

import {
  REPAINT_FEATURES, PAINT_CONDITION_LABELS,
} from "./repaintDefaults";
import { computeDimLetterPaint } from "./dimLetterPaintCalculator";

const num = (v, d = 0) => {
  const n = parseFloat(v);
  return Number.isFinite(n) ? n : d;
};

// Default fallbacks (mirror REPAINT_DEFAULTS) so calc still works if settings haven't been written yet.
const SETTING_FALLBACKS = {
  maintenance_repaint_coverage_sqft_per_gallon: 350,
  maintenance_repaint_paint_cost_per_gallon: 55,
  maintenance_repaint_primer_coats: 1,
  maintenance_repaint_finish_coats: 2,
  maintenance_repaint_sqft_per_hour: 60,
  maintenance_repaint_feat_dimensional_letters: 1.35,
  maintenance_repaint_feat_painted_letters: 1.25,
  maintenance_repaint_feat_applied_vinyl: 1.15,
  maintenance_repaint_feat_complex_layering: 1.40,
  maintenance_repaint_condition_step_pct: 8,
};

const settingNum = (settings, key) => num(settings?.[key], SETTING_FALLBACKS[key]);

export const isMonumentRepaint = (item) => {
  if (!item) return false;
  if (item.sign_type !== "monument_sign") return false;
  return (item.actions || []).includes("repaint");
};

// Default config seeded onto a service item the first time monument + repaint
// is selected.
export const defaultMonumentRepaintConfig = () => ({
  length_ft: 8,
  height_ft: 4,
  return_depth_in: 6,
  paint_mode: "entire_panel",  // "entire_panel" | "returns_only"
  features: [],                // ids from REPAINT_FEATURES (only used when entire_panel)
  retainer_width_in: 2,        // only used when returns_only
  paint_condition: 3,          // 1-10
  paint_both_sides: true,      // monument typically has 2 painted faces
  // Dimensional-letter painting — only relevant when "dimensional_letters" feature is on
  dim_letter_paint: {
    enabled: false,
    qty: 6,
    avg_height_in: 12,
    thickness_in: 1,
    second_color_mask: "none", // "none" | "paint_mask"
  },
});

// SQFT computation. Length/Height in feet, return_depth in inches.
// Mode "entire_panel"  → face area × (1 or 2 sides) + perimeter band of returns
//                       (perimeter × return_depth converted to ft)
// Mode "returns_only"  → perimeter × retainer_width converted to ft
export const computeRepaintSqft = (cfg) => {
  if (!cfg) return { face_sqft: 0, returns_sqft: 0, total_sqft: 0, perimeter_ft: 0 };
  const L = Math.max(0, num(cfg.length_ft));
  const H = Math.max(0, num(cfg.height_ft));
  const perimeter_ft = 2 * (L + H);
  const sides = cfg.paint_both_sides ? 2 : 1;

  if (cfg.paint_mode === "returns_only") {
    const retainerFt = Math.max(0, num(cfg.retainer_width_in)) / 12;
    const returns_sqft = perimeter_ft * retainerFt;
    return { face_sqft: 0, returns_sqft, total_sqft: returns_sqft, perimeter_ft };
  }

  // entire_panel
  const face_sqft = L * H * sides;
  const returnDepthFt = Math.max(0, num(cfg.return_depth_in)) / 12;
  const returns_sqft = perimeter_ft * returnDepthFt;
  return { face_sqft, returns_sqft, total_sqft: face_sqft + returns_sqft, perimeter_ft };
};

// Feature multiplier — multiplicative across features when paint_mode = entire_panel.
export const featureMultiplier = (cfg, settings) => {
  if (!cfg || cfg.paint_mode !== "entire_panel") return 1;
  const selected = new Set(cfg.features || []);
  let mult = 1;
  REPAINT_FEATURES.forEach(f => {
    if (selected.has(f.id)) mult *= settingNum(settings, f.setting);
  });
  return mult;
};

// Condition multiplier — 1 + step% × (level - 1), clamped at level 1..10.
export const conditionMultiplier = (cfg, settings) => {
  const level = Math.min(10, Math.max(1, Math.round(num(cfg?.paint_condition, 1))));
  const stepPct = settingNum(settings, "maintenance_repaint_condition_step_pct");
  return 1 + (stepPct / 100) * (level - 1);
};

// Master compute. Returns null if item isn't a monument repaint.
export const computeMonumentRepaint = (item, settings) => {
  if (!isMonumentRepaint(item)) return null;
  const cfg = item.repaint_config || defaultMonumentRepaintConfig();
  const { face_sqft, returns_sqft, total_sqft, perimeter_ft } = computeRepaintSqft(cfg);

  const coverage = settingNum(settings, "maintenance_repaint_coverage_sqft_per_gallon") || 350;
  const pricePerGal = settingNum(settings, "maintenance_repaint_paint_cost_per_gallon");
  const primerCoats = Math.max(0, settingNum(settings, "maintenance_repaint_primer_coats"));
  const finishCoats = Math.max(0, settingNum(settings, "maintenance_repaint_finish_coats"));
  const sqftPerHour = settingNum(settings, "maintenance_repaint_sqft_per_hour") || 60;

  const totalCoats = primerCoats + finishCoats;
  const paintedSqft = total_sqft * totalCoats;
  const gallons = paintedSqft / coverage;
  const paintMaterialCost = gallons * pricePerGal;

  const featMult = featureMultiplier(cfg, settings);
  const condMult = conditionMultiplier(cfg, settings);
  let labor_hours = (total_sqft / sqftPerHour) * featMult * condMult;

  // Add Painted Dimensional Letters (Paint Estimator rates) when enabled
  const featureSet = new Set(cfg.features || []);
  const dl = (featureSet.has("dimensional_letters") && cfg.paint_mode === "entire_panel")
    ? computeDimLetterPaint(cfg, settings)
    : null;
  let dimLetterCost = 0;
  if (dl) {
    dimLetterCost = dl.letters_total_added_cost;
    labor_hours += (dl.letters_labor_hours || 0) + (dl.mask_labor_hours || 0);
  }

  return {
    cfg,
    face_sqft, returns_sqft, total_sqft, perimeter_ft,
    coverage, pricePerGal, primerCoats, finishCoats, totalCoats,
    gallons,
    paint_material_cost: paintMaterialCost + dimLetterCost,
    feature_multiplier: featMult,
    condition_multiplier: condMult,
    paint_condition_label: PAINT_CONDITION_LABELS[Math.min(9, Math.max(0, (cfg.paint_condition || 1) - 1))],
    labor_hours,
    dim_letter_paint: dl,
  };
};

// Pure calculation helpers for Sign Maintenance estimates.
// Mirrors components/channelLetterInstall/installCalculator structurally but
// is driven by the MaintenanceActionRate matrix (sign_type × action × size).

import { sizeAxisFor } from "./constants";
import { computeMonumentRepaint, isMonumentRepaint } from "./repaintCalculator";

const MIN_TO_HR = 1 / 60;

// Map a size id to the MaintenanceActionRate field that stores its minutes.
const SIZE_TO_FIELD = {
  extra_small: "base_minutes_xs",
  small: "base_minutes_s",
  medium: "base_minutes_m",
  large: "base_minutes_l",
  extra_large: "base_minutes_xl",
  extra_extra_large: "base_minutes_xxl",
  cab_small: "base_minutes_cab_s",
  cab_medium: "base_minutes_cab_m",
  cab_large: "base_minutes_cab_l",
  cab_extra_large: "base_minutes_cab_xl",
};

export const emptyServiceItem = () => ({
  description: "",
  sign_type: "flush_channel",
  size: "medium",
  qty: 10,
  installation_height_feet: 12,
  actions: [],   // array of action ids
  materials: [], // array of {inventory_item_id, item_name, quantity, unit_cost, total_cost}
});

// Look up the MaintenanceActionRate row for (sign_type, action) and return base minutes for the chosen size.
const minutesForActionOnSize = (rates, signType, action, size) => {
  const rate = (rates || []).find(r => r.sign_type === signType && r.action === action);
  if (!rate) return 0;
  // Honor the per-sign-type enable toggle. Disabled rate rows contribute 0 minutes.
  if (rate.is_enabled === false) return 0;
  const field = SIZE_TO_FIELD[size];
  if (!field) return parseFloat(rate.base_minutes_flat) || 0;
  return parseFloat(rate[field]) || 0;
};

// Calc one service item: total labor hours + cost for ALL actions performed on it.
export const calcServiceItem = (item, settings, rates, inventory) => {
  const techRate = parseFloat(settings.maintenance_tech_rate) || 65;
  const axis = sizeAxisFor(item.sign_type);
  const qty = parseFloat(item.qty) || 0;

  let totalMinutes = 0;
  (item.actions || []).forEach(actionId => {
    // Monument repaint has its own specialized estimator — skip the rate-matrix
    // contribution for that single action, we add it below.
    if (actionId === "repaint" && isMonumentRepaint(item)) return;
    const perUnit = minutesForActionOnSize(rates, item.sign_type, actionId, item.size);
    // For cabinet axis, qty acts as # cabinets; for letter axis, qty acts as # letters.
    totalMinutes += perUnit * (axis === "cabinet" ? Math.max(qty, 1) : qty);
  });

  let laborHours = totalMinutes * MIN_TO_HR;

  // Specialized contribution: Monument Sign repaint
  let repaintPaintCost = 0;
  const repaint = computeMonumentRepaint(item, settings);
  if (repaint) {
    laborHours += repaint.labor_hours;
    repaintPaintCost = repaint.paint_material_cost;
  }

  const laborCost = laborHours * techRate;

  // Recompute materials based on current item state.
  const materials = (item.materials || []).map(m => {
    const inv = (inventory || []).find(i => i.id === (m.maintenance_rule_id || m.inventory_item_id));
    if (!inv) return { ...m, total_cost: (parseFloat(m.unit_cost) || 0) * (parseFloat(m.quantity) || 0) };
    return materialFromInventory(inv, item, m);
  });
  const materialsCost = materials.reduce((s, m) => s + (parseFloat(m.total_cost) || 0), 0) + repaintPaintCost;

  return {
    ...item,
    materials,
    labor_hours: laborHours,
    labor_cost: laborCost,
    materials_cost: materialsCost,
    repaint_calc: repaint || undefined,
    item_total_cost: laborCost + materialsCost,
  };
};

const usageBasisQuantity = (item, basis) => {
  if (basis === "per_letter") return parseFloat(item.qty) || 0;
  if (basis === "per_cabinet") return Math.max(parseFloat(item.qty) || 0, 1);
  if (basis === "per_linear_foot") return parseFloat(item.linear_feet) || 0;
  if (basis === "per_sqft") return parseFloat(item.face_sqft) || 0;
  return 1;
};

export const materialFromInventory = (inv, item, existing = null) => {
  const linked = !!(inv.inventory_entity && inv.inventory_item_id);
  if (linked) {
    const basis = inv.usage_basis || "per_service_item";
    const multiplier = Math.max(0, parseFloat(inv.usage_multiplier) || 0);
    const rawQuantity = usageBasisQuantity(item, basis) * multiplier;
    const autoQuantity = inv.usage_rounding === "ceil_whole" ? Math.ceil(rawQuantity) : rawQuantity;
    const quantity = existing?.quantity_override ? Math.max(0, parseFloat(existing.quantity) || 0) : autoQuantity;
    const unitCost = Number.isFinite(Number(inv._master_unit_cost))
      ? Number(inv._master_unit_cost)
      : parseFloat(existing?.unit_cost) || 0;
    return {
      ...(existing || {}),
      maintenance_rule_id: inv.id,
      inventory_entity: inv.inventory_entity,
      inventory_item_id: inv.inventory_item_id,
      inventory_item_name: inv.inventory_item_name || inv._display_name || inv.item_name,
      item_name: inv._display_name || inv.inventory_item_name || inv.item_name,
      pricing_mode: inv._master_pricing_mode || existing?.pricing_mode || inv.pricing_mode,
      usage_basis: basis,
      usage_multiplier: multiplier,
      usage_rounding: inv.usage_rounding || "none",
      unit: inv._master_unit || existing?.unit || inv.unit || "unit",
      unit_cost: unitCost,
      auto_quantity: autoQuantity,
      quantity,
      quantity_override: !!existing?.quantity_override,
      link_missing: !!inv._master_missing,
      total_cost: unitCost * quantity,
    };
  }

  const m = {
    ...(existing || {}),
    maintenance_rule_id: inv.id,
    inventory_item_id: inv.id,
    item_name: inv.item_name,
    pricing_mode: inv.pricing_mode,
    unit: inv.unit || inv.pricing_mode || "unit",
    unit_cost: 0, quantity: 0, total_cost: 0,
  };
  const sizeKey = `cost_${item.size}`;
  if (inv.pricing_mode === "per_letter_flat") {
    m.unit_cost = parseFloat(inv.cost_per_letter) || 0;
    m.quantity = parseFloat(item.qty) || 0;
  } else if (inv.pricing_mode === "per_letter_by_size" || inv.pricing_mode === "per_cabinet_by_size") {
    m.unit_cost = parseFloat(inv[sizeKey]) || 0;
    m.quantity = parseFloat(item.qty) || 0;
  } else if (inv.pricing_mode === "per_cabinet_flat") {
    m.unit_cost = parseFloat(inv.cost_per_cabinet) || 0;
    m.quantity = parseFloat(item.qty) || 0;
  } else if (inv.pricing_mode === "per_linear_foot") {
    m.unit_cost = parseFloat(inv.cost_per_foot) || 0;
    m.quantity = parseFloat(item.linear_feet) || 0;
  } else if (inv.pricing_mode === "per_sqft") {
    m.unit_cost = parseFloat(inv.cost_per_sqft) || 0;
    m.quantity = parseFloat(item.face_sqft) || 0;
  } else if (inv.pricing_mode === "per_project_flat") {
    m.unit_cost = parseFloat(inv.cost_flat) || 0;
    m.quantity = 1;
  }
  if (existing?.quantity_override) m.quantity = Math.max(0, parseFloat(existing.quantity) || 0);
  m.quantity_override = !!existing?.quantity_override;
  m.auto_quantity = m.quantity;
  m.total_cost = m.unit_cost * m.quantity;
  return m;
};

// Pull default materials for a service item based on multi-axis tagging.
export const defaultMaterialsForItem = (item, inventory) => {
  return (inventory || [])
    .filter(inv => {
      if (inv.is_active === false || !inv.is_default || inv._master_missing) return false;
      const types = inv.applies_to_item_types || [];
      const sizes = inv.applies_to_sizes || [];
      const actions = inv.applies_to_actions || [];
      if (types.length > 0 && !types.includes(item.sign_type)) return false;
      if (sizes.length > 0 && !sizes.includes(item.size)) return false;
      if (actions.length > 0) {
        const itemActions = item.actions || [];
        // Only attach if at least one of this material's actions is being performed.
        if (!actions.some(a => itemActions.includes(a))) return false;
      }
      return true;
    })
    .map(inv => materialFromInventory(inv, item));
};

// Project rollup
export const calcProjectTotals = (project) => {
  const items = project.items || [];
  const total_materials_cost = items.reduce((s, it) => s + (parseFloat(it.materials_cost) || 0), 0);
  const labor_cost = items.reduce((s, it) => s + (parseFloat(it.labor_cost) || 0), 0);
  const labor_hours = items.reduce((s, it) => s + (parseFloat(it.labor_hours) || 0), 0);

  const total_equipment_cost = (project.selected_equipment || []).reduce((s, e) => s + (parseFloat(e.total_cost) || 0), 0);
  const total_personnel_cost = (project.personnel || []).reduce((s, p) => s + (parseFloat(p.total_cost) || 0), 0);

  const pct = parseFloat(project.supplies_percent_of_materials);
  const suppliesPct = isNaN(pct) ? 10 : pct;
  const extra = parseFloat(project.extra_supplies_cost) || 0;
  const total_supplies_cost = total_materials_cost * (suppliesPct / 100) + extra;

  const total_travel_cost = parseFloat(project.total_travel_cost) || 0;

  const subtotal = labor_cost + total_materials_cost + total_supplies_cost + total_equipment_cost + total_personnel_cost + total_travel_cost;
  const markupPct = parseFloat(project.markup_percent) || 0;
  const markup_amount = subtotal * (markupPct / 100);
  const total_cost = subtotal + markup_amount;

  return {
    labor_hours, labor_cost, total_materials_cost, total_supplies_cost,
    total_equipment_cost, total_personnel_cost, total_travel_cost,
    subtotal, markup_amount, total_cost,
  };
};

// F-23a — channel-module sell-price boundary for the shared pricing engine.
//
// customerPricing.sourceProjectEconomics calls this for every channel_letters
// record. It injects the shared engine (pricePart + the PricingTemplate seam
// from pricingTemplateModel) into base44/shared/channelPricingWire.ts and
// returns the wired economics, or null when the record carries no engine
// config — in which case the caller keeps today's numbers byte-identically.
//
// Config detection (see channelPricingWire.ts entity contract):
//   record.pricing_engine|engine_pricing|pricing_tier_config|pricing_context|
//   customer_pricing.engine_context|pricing_engine — context block;
//   per-line descriptors on items[]/letter_purchases[]/selected_equipment[]/
//   personnel[] — part/pricing/tier_ref/fixed_price/per_unit_breaks/
//   markup_pct/market_*/pricing_template(_id)/machine fields.
// Legacy customer_pricing/pricing_tier/customer_tier alone never engage —
// they only feed an explicit pricing_engine block as the customer-tier hint.

import { pricePart } from "../../../../base44/shared/pricingEngine.ts";
import { resolveTemplatePrice, templatePartDescriptor } from "../../../../base44/shared/pricingTemplateModel.ts";
import { channelEngineEconomics } from "../../../../base44/shared/channelPricingWire.ts";

const ENGINE = { pricePart, resolveTemplatePrice, templatePartDescriptor };

/**
 * @param {object} record  saved ChannelLetterInstallation record
 * @param {object} economics  { internalCost, customerPrice } — today's values
 * @returns {object|null}  wired economics ({wired, internalCost, customerPrice,
 *   sell, lines, context, chain}) or null when the record is not engine-configured
 */
export function channelSellEconomics(record, economics) {
  const wired = channelEngineEconomics({
    record,
    internalCost: economics?.internalCost,
    customerPrice: economics?.customerPrice,
    engine: ENGINE,
  });
  return wired?.wired === true ? wired : null;
}

// Vinyl sell-price engine wire (F-23b) — module-side glue.
//
// The shared wire (base44/shared/vinylPricingWire.ts) is intentionally
// import-free; this file is the composition root that injects the real engine
// functions and merges caller-supplied registries with the record-embedded
// engine context. Wired into customerPricing.sourceProjectEconomics for
// module_key "vinyl" — when no vinyl line carries pricing-engine config the
// resolution is a passthrough and the module sell price is returned verbatim
// (zero regression).
//
// Registry context (`pricingContext`) is OPTIONAL today: config embedded on
// the record/items (item pricing fields, engine_pricing blocks, embedded
// templates/tier rules) resolves without any entity reads. Callers that have
// PricingTierMatrix / PricingTemplate / GlobalPricingTier / MarkupTier rows
// loaded may pass them as { tierRules|tier_rules, templates, tiers,
// customerTier|customer_tier, defaultMarkupPct|default_markup_pct, now } to
// unlock registry-backed tier/template references.

import { pricePart, matrixRowsToRules } from "../../../../base44/shared/pricingEngine.ts";
import { resolveTemplatePrice, templatePartDescriptor } from "../../../../base44/shared/pricingTemplateModel.ts";
import {
  resolveVinylSellPricing,
  vinylConfigScan,
  vinylPricingContextOf,
} from "../../../../base44/shared/vinylPricingWire.ts";

const ENGINE = Object.freeze({ pricePart, resolveTemplatePrice, templatePartDescriptor });

/**
 * Full resolution — engine-priced sell for config-carrying vinyl lines.
 * Never throws: malformed input/config degrades to a passthrough result.
 *
 * @param {object} record       VinylProject-like record
 * @param {object} opts
 * @param {number} opts.baselineSell  module sell price (record.total_cost)
 * @param {number} [opts.internalCost] module internal cost (record.subtotal)
 * @param {object} [opts.pricingContext] caller-loaded registries (optional)
 * @param {*}      [opts.now]    effective-window override (tests)
 * @returns {object} resolveVinylSellPricing result ({applied, customer_price,
 *          passthrough, lines, chain, warnings, ...})
 */
export function resolveVinylEngineSell(record, { baselineSell, internalCost, pricingContext, now } = {}) {
  try {
    const caller = pricingContext && typeof pricingContext === "object" ? { ...pricingContext } : {};
    // Normalize caller chart rows through the engine's entity adapter so
    // PricingTierMatrix spellings (unit_breaks aliases, status windows) resolve
    // exactly like the pricing admin path.
    const rawRules = caller.tierRules ?? caller.tier_rules ?? caller.tier_matrix;
    if (Array.isArray(rawRules) && rawRules.length) {
      caller.tierRules = matrixRowsToRules(rawRules, { now: caller.now ?? now });
    }
    const context = vinylPricingContextOf(record, caller);
    return resolveVinylSellPricing({ record, baselineSell, internalCost, context, engine: ENGINE, now });
  } catch {
    // The sell-price seam must never break estimate rendering — a malformed
    // record or config degrades to the module baseline, not an exception.
    return { applied: false, passthrough: true, reason: "no_engine", customer_price: baselineSell, warnings: [] };
  }
}

/**
 * Seam helper — engine-owned economics for a vinyl source record.
 * Returns null when no vinyl line carries pricing config (the caller then
 * keeps today's numbers byte-identically); when config resolves the engine
 * owns the sell side — including over a legacy saved customer_pricing
 * snapshot (parity with the F-23a channel wire).
